import{R as e,e as i,f as a,U as o}from"./chunks/framework.ywem4qy5.js";const b=JSON.parse('{"title":"Submissions","description":"","frontmatter":{},"headers":[],"relativePath":"submissions/overview.md","filePath":"submissions/overview.md","lastUpdated":1776774863000}'),t={name:"submissions/overview.md"};function n(r,s,l,u,m,h){return i(),a("div",null,[...s[0]||(s[0]=[o('<h1 id="submissions" tabindex="-1">Submissions <a class="header-anchor" href="#submissions" aria-label="Permalink to &quot;Submissions&quot;">​</a></h1><p>Submissions are the saved records created when someone interacts with a Formie form.</p><p>They can represent a completed submission, a partially saved draft, or a submission that has been marked as spam. Once a submission exists, you can review it in the control panel, organize it with statuses, export its data, relate it to other elements, or render it back into the front end for editing.</p><h2 id="submission-states" tabindex="-1">Submission states <a class="header-anchor" href="#submission-states" aria-label="Permalink to &quot;Submission states&quot;">​</a></h2><p>Formie tracks a few built-in submission states:</p><ul><li><strong>complete</strong> submissions have finished the normal submission flow</li><li><strong>incomplete</strong> submissions are partially saved, such as save-and-continue drafts or multi-page progress</li><li><strong>spam</strong> submissions have been screened and marked as spam</li></ul><p>These are system states. They describe what happened during submission processing.</p><p>Custom <a href="/submissions/statuses">Statuses</a> are different. A status is your team&#39;s workflow label on top of the saved submission, such as <code>new</code>, <code>approved</code>, or <code>closed</code>.</p><h2 id="common-ways-to-work-with-submissions" tabindex="-1">Common ways to work with submissions <a class="header-anchor" href="#common-ways-to-work-with-submissions" aria-label="Permalink to &quot;Common ways to work with submissions&quot;">​</a></h2><h3 id="organize-them-with-statuses" tabindex="-1">Organize them with statuses <a class="header-anchor" href="#organize-them-with-statuses" aria-label="Permalink to &quot;Organize them with statuses&quot;">​</a></h3><p>Use <a href="/submissions/statuses">Statuses</a> when your team needs labels for review, follow-up, or internal processing after a submission has been saved.</p><h3 id="export-submission-data" tabindex="-1">Export submission data <a class="header-anchor" href="#export-submission-data" aria-label="Permalink to &quot;Export submission data&quot;">​</a></h3><p>Use <a href="/submissions/exporting">Exporting</a> when you need spreadsheets, reporting output, or a portable snapshot of saved submission data.</p><h3 id="relate-submissions-to-other-elements" tabindex="-1">Relate submissions to other elements <a class="header-anchor" href="#relate-submissions-to-other-elements" aria-label="Permalink to &quot;Relate submissions to other elements&quot;">​</a></h3><p>Use <a href="/submissions/relations">Relations</a> when a submission belongs to another Craft element such as an entry or product, or when you want to look up related submissions later.</p><h3 id="select-submissions-from-other-elements" tabindex="-1">Select submissions from other elements <a class="header-anchor" href="#select-submissions-from-other-elements" aria-label="Permalink to &quot;Select submissions from other elements&quot;">​</a></h3><p>Use <a href="/submissions/element-field">Element Field</a> when you want another Craft element to choose and store a reference to a Formie submission.</p><h3 id="let-users-edit-saved-submissions" tabindex="-1">Let users edit saved submissions <a class="header-anchor" href="#let-users-edit-saved-submissions" aria-label="Permalink to &quot;Let users edit saved submissions&quot;">​</a></h3><p>If you need to render an existing submission back into the front end so a user can update it, see <a href="/templates/editing-submissions">Editing Submissions</a>.</p><h2 id="developer-access" tabindex="-1">Developer access <a class="header-anchor" href="#developer-access" aria-label="Permalink to &quot;Developer access&quot;">​</a></h2><p>If you are working with submissions in templates or custom code:</p><ul><li>use <a href="/getting-elements/submission-queries">Submission Queries</a> to fetch submissions in Twig or PHP</li><li>use <a href="/developers/submission-workflow">Submission Workflow</a> when you need to hook into submission processing stages or tasks</li><li>use <a href="/developers/submission-content">Submission Content</a> when you need the right value format for output, exports, summaries, emails, or integrations</li><li>use <a href="/reference/submission">Submission</a> for the public properties and methods available on the element itself</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/submissions/statuses">Statuses</a></li><li><a href="/submissions/exporting">Exporting</a></li><li><a href="/submissions/relations">Relations</a></li><li><a href="/submissions/element-field">Element Field</a></li><li><a href="/templates/editing-submissions">Editing Submissions</a></li><li><a href="/getting-elements/submission-queries">Submission Queries</a></li><li><a href="/developers/submission-workflow">Submission Workflow</a></li></ul>',24)])])}const p=e(t,[["render",n]]);export{b as __pageData,p as default};
